// 2. UI & LOBBY MENU EVENTS
// ==========================================
document.getElementById('btn-create-game').addEventListener('click', () => {
    const customCode = document.getElementById('custom-map-code').value.trim();
    socket.emit('createRoom', { 
        username: usernameInput.value, 
        mapCode: customCode 
    });
});

document.getElementById('btn-join-private').addEventListener('click', () => {
    const code = roomCodeInput.value.trim();
    if (code) socket.emit('joinRoom', { roomCode: code, username: usernameInput.value });
});

document.getElementById('btn-test-map').addEventListener('click', () => {
    const customCode = document.getElementById('custom-map-code').value.trim();
    socket.emit('createRoom', { 
        username: usernameInput.value || 'Tester', 
        mapCode: customCode // Now it uses your pasted code if available!
    });
    setTimeout(() => socket.emit('startGame'), 200); 
});

btnStartGame.addEventListener('click', () => {
    socket.emit('startGame');
});

socket.on('errorMsg', (msg) => { errorMsg.innerText = msg; });

socket.on('roomCreated', (code) => { showLobby(code); });
socket.on('roomJoined', (code) => { showLobby(code); });

function showLobby(code) {
    mainMenu.style.display = 'none';
    lobbyMenu.style.display = 'block';
    document.getElementById('lobby-room-code').innerText = code;
}

socket.on('lobbyUpdate', (data) => {
    playerList.innerHTML = '';
    data.players.forEach(p => {
        const li = document.createElement('li');
        li.innerText = `${p.name} (Player ${p.id})`;
        li.style.color = players[p.id].color;
        playerList.appendChild(li);
    });

    if (socket.id === data.host) {
        btnStartGame.style.display = 'block';
        waitingMsg.style.display = 'none';
    } else {
        btnStartGame.style.display = 'none';
        waitingMsg.style.display = 'block';
    }
});

socket.on('gameStarted', () => {
    uiLayer.style.display = 'none';
    canvas.style.display = 'block';
    isGameRunning = true;
    requestAnimationFrame(gameLoop); 
});

// ==========================================
// 3. NETWORK LOGIC (IN-GAME)
// ==========================================
socket.on('initPlayer', (id) => {
    myPlayerId = id;
    document.title = `Jelly Go - Player ${myPlayerId}`;
});

socket.on('syncState', (serverState) => {
    serverState.buildings.forEach(serverB => {
        if (!clientBuildings[serverB.id]) {
            clientBuildings[serverB.id] = new Building(serverB);
        } else {
            clientBuildings[serverB.id].update(serverB);
        }
    });
    
    clientPackages = serverState.packages || [];
    clientProjectiles = serverState.projectiles || [];

    selectedBuildings = selectedBuildings.map(b => clientBuildings[b.id]).filter(Boolean);
    if (hoveredBuilding) updateUpgradeOptions();
});


function drawGround(ctx, x, y, r) {
    ctx.save();
    // The ground is absolutely fixed relative to the click coordinate!
    ctx.translate(x, y + r * 0.4); 

    ctx.beginPath();
    ctx.arc(0, 0, r * 1.3, 0, Math.PI, false);
    ctx.bezierCurveTo(r * 1.3, r * 0.8, -r * 1.3, r * 0.8, -r * 1.3, 0);
    let grad = ctx.createLinearGradient(0, 0, 0, r);
    grad.addColorStop(0, '#1B3B5A'); grad.addColorStop(1, '#0D1E30');
    ctx.fillStyle = grad; ctx.fill();
    ctx.lineWidth = 2; ctx.strokeStyle = '#0B1622'; ctx.stroke();

    ctx.beginPath(); ctx.ellipse(0, 0, r * 1.3, r * 0.35, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#21466B'; ctx.fill(); ctx.stroke();

    ctx.beginPath(); ctx.ellipse(0, 0, r * 1.1, r * 0.25, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#0B1622'; ctx.fill();
    ctx.restore();
}

function drawCustomUnit(ctx, b, color, maxJellies, isSelected, calib) {
    const fillRatio = Math.min(1, Math.max(0, b.jellyCount / maxJellies));
    const bulgeBonus = Math.min(0.10, b.jellyCount / 10000); 
    const r = b.radius * (1 + bulgeBonus); 
    const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
    const path = SVG_PATHS[pathKey] || SVG_PATHS['basic'];
    
    const SVG_DRAWN_SIZE = 2800; 
    const CENTER_X = 1490; const CENTER_Y = 1450;
    
    ctx.save();
    // Move to the exact physical spawn point, plus the custom SVG offset
    ctx.translate(b.x + calib.unitX, b.y + calib.unitY);
    
    const scale = (r * calib.s) / SVG_DRAWN_SIZE; 
    ctx.scale(scale, scale);
    ctx.translate(-CENTER_X, -CENTER_Y);

    ctx.fillStyle = color; ctx.globalAlpha = b.status === 'frozen' ? 0.2 : 0.4; ctx.fill(path);

    ctx.save(); ctx.clip(path); 
    const liquidHeight = SVG_DRAWN_SIZE * 1.1; 
    const shapeBottomY = CENTER_Y + (SVG_DRAWN_SIZE / 2);
    const liquidY = shapeBottomY - (liquidHeight * fillRatio); 
    ctx.fillStyle = color; ctx.globalAlpha = b.status === 'frozen' ? 0.5 : 1.0; 
    ctx.fillRect(CENTER_X - (SVG_DRAWN_SIZE / 2), liquidY, SVG_DRAWN_SIZE, liquidHeight);
    ctx.restore(); 

    const baseLineWidth = isSelected ? 3 : (b.type === 'fort' ? 4 : 2);
    ctx.lineWidth = baseLineWidth / scale; 
    if (b.status === 'sick') ctx.strokeStyle = '#2ecc71'; 
    else if (isSelected) ctx.strokeStyle = '#ffffff'; 
    else ctx.strokeStyle = "rgba(0, 0, 0, 0.4)"; 
    ctx.stroke(path);
    ctx.restore();
}

function drawEyes(ctx, b, calib) {
    const eyeCount = (b.type === 'basic' || b.type === 'building') ? 2 : 1;
    const isHovered = (typeof hoveredBuilding !== 'undefined' && hoveredBuilding && hoveredBuilding.id === b.id);
    const hasPackagesNearby = typeof clientPackages !== 'undefined' && clientPackages.some(p => Math.hypot(p.x - b.x, p.y - b.y) < b.radius * 2.5);
    
    // Neutrals wake up if hovered, packages are near, or screaming for help
    const isSleeping = (b.ownerId === 0 && !isHovered && !hasPackagesNearby && b.helpTimer === 0);

    // --- NEW RANDOMIZED ANIMATION TIMING ---
    // Initialize a random future time for this specific unit if it doesn't have one
    if (!b.nextSuspicious) {
        b.nextSuspicious = Date.now() + 5000 + Math.random() * 15000; // Between 5s and 20s from now
    }

    let isSuspicious = false;
    let suspiciousElapsed = 0;

    // Only look around if awake, owned by a player, and NOT frozen
    if (!isSleeping && b.ownerId > 0 && b.status !== 'frozen') {
        let now = Date.now();
        if (now >= b.nextSuspicious) {
            isSuspicious = true;
            suspiciousElapsed = now - b.nextSuspicious;
            
            // The animation lasts exactly 1.5 seconds (1500ms)
            if (suspiciousElapsed > 1500) {
                isSuspicious = false;
                // Schedule the next animation 5 to 20 seconds into the future
                b.nextSuspicious = now + 5000 + Math.random() * 15000; 
            }
        }
    }

    const eyeR = b.radius * 0.22;
    const eyeX = b.x + calib.eyeX;
    const eyeY = b.y + calib.eyeY;

    ctx.save();
    ctx.lineWidth = 2;

    const drawSingleEye = (ex) => {
        // Frozen units force their eyes closed!
        if (isSleeping || b.status === 'frozen') {
            ctx.strokeStyle = '#000000';
            ctx.beginPath(); ctx.arc(ex, eyeY, eyeR * 0.8, 0.1 * Math.PI, 0.9 * Math.PI, false); ctx.stroke();
        } else {
            ctx.fillStyle = '#ffffff'; ctx.strokeStyle = '#000000'; ctx.beginPath();
            if (isSuspicious) {
                ctx.arc(ex, eyeY + eyeR * 0.4, eyeR, 0, Math.PI, true);
                ctx.lineTo(ex - eyeR, eyeY + eyeR * 0.4);
            } else {
                ctx.arc(ex, eyeY, eyeR, 0, Math.PI * 2);
            }
            ctx.fill(); ctx.stroke();

            ctx.fillStyle = '#000000';
            let pupX = ex;
            let pupY = isSuspicious ? eyeY + eyeR * 0.1 : eyeY;
            
            // Dart left, then right based on the 1.5s elapsed time
            if (isSuspicious) {
                let lookCycle = suspiciousElapsed / 1500;
                if (lookCycle < 0.33) pupX -= eyeR * 0.4;
                else if (lookCycle > 0.66) pupX += eyeR * 0.4;
            }
            ctx.beginPath(); ctx.arc(pupX, pupY, eyeR * 0.4, 0, Math.PI * 2); ctx.fill();
        }
    };

    if (eyeCount === 1) drawSingleEye(eyeX);
    else { drawSingleEye(eyeX - eyeR * 1.1); drawSingleEye(eyeX + eyeR * 1.1); }

    if (isSleeping) {
        ctx.fillStyle = '#ffffff'; ctx.font = 'bold 12px Arial';
        ctx.fillText('z', eyeX + b.radius * 0.4, eyeY - b.radius * 0.4);
        ctx.font = 'bold 10px Arial';
        ctx.fillText('z', eyeX + b.radius * 0.7, eyeY - b.radius * 0.7);
        ctx.font = 'bold 8px Arial';
        ctx.fillText('z', eyeX + b.radius * 0.9, eyeY - b.radius * 1.0);
    }
    ctx.restore();
}

function drawHelpBubble(ctx, b) {
    ctx.save();
    ctx.translate(b.x + 24, b.y - 44); // Simple fixed bubble relative to center
    ctx.fillStyle = '#ffffff'; ctx.strokeStyle = '#000000'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.roundRect(0, -25, 45, 20, 5);
    ctx.moveTo(10, -5); ctx.lineTo(5, 5); ctx.lineTo(20, -5);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#000000'; ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText("Help!", 22.5, -15);
    ctx.restore();
}





// ==========================================
// 4. BUILDING CLASS
// ==========================================
class Building {
    constructor(data) { this.update(data); }

    update(data) {
        this.id = data.id;
        this.x = data.x;
        this.y = data.y;
        this.radius = data.radius;
        this.ownerId = data.ownerId;
        this.jellyCount = data.jellyCount;
        this.type = data.type;
        this.level = data.level;
        this.status = data.status;
        this.activePotion = data.activePotion;
        this.potionRatio = data.potionRatio;
        this.helpTimer = data.helpTimer || 0; // Sync the timer
    }

    canUpgrade() {
        if (this.ownerId !== myPlayerId) return false;
        if (this.type === 'basic') return this.jellyCount >= 5;
        const cost = UPGRADE_DATA[this.type][this.level];
        return cost !== null && this.jellyCount >= cost;
    }

draw(ctx) {
        ctx.save();

        if (this.type === 'fort' && this.ownerId > 0 && this.status !== 'frozen') {
            const attackRadius = this.radius * 2.5;
            ctx.beginPath(); ctx.arc(this.x, this.y, attackRadius, 0, Math.PI * 2);
            ctx.strokeStyle = "rgba(255, 255, 255, 0.2)"; ctx.lineWidth = 1; ctx.setLineDash([5, 5]); ctx.stroke(); ctx.setLineDash([]); 
        }

        const pathKey = this.type === 'basic' ? 'basic' : `${this.type}_${this.level || 1}`;
        const calib = UNIT_CALIBRATION[pathKey] || { s: 2.4, unitX: 0, unitY: 0, eyeX: 0, eyeY: 0, textX: 0, textY: 0, upgX: 25, upgY: 25, menuX: 0, menuY: -50 };

        // 1. Draw Ground (Fixed, Unmovable)
        drawGround(ctx, this.x, this.y, this.radius);


        // 3. Draw Unit (SVG)
        const pColor = players[this.ownerId] ? players[this.ownerId].color : '#bdc3c7';
        let maxCap = 10;
        if (this.type === 'basic') maxCap = 10;
        else if (this.maxJelliesOverride) maxCap = this.maxJelliesOverride;
        else if (typeof BUILDING_CONFIGS !== 'undefined' && BUILDING_CONFIGS[this.type] && BUILDING_CONFIGS[this.type][this.level]) {
            maxCap = BUILDING_CONFIGS[this.type][this.level].maxJellies;
        }
        const isSelected = selectedBuildings.some(b => b.id === this.id);
        drawCustomUnit(ctx, this, pColor, maxCap, isSelected, calib);

        // 4. Draw Eyes
        drawEyes(ctx, this, calib);

        // 5. Draw Text
        ctx.fillStyle = '#ffffff'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.font = 'bold 20px Arial';
        ctx.fillText(Math.floor(this.jellyCount), this.x + calib.textX, this.y + calib.textY); 

        // 6. Draw Predictive Help Bubble
        if (this.helpTimer > 0 && this.status !== 'frozen') {
            drawHelpBubble(ctx, this);
        }

        // 7. Draw Upgrade Dot
        if (this.canUpgrade()) {
            ctx.beginPath();
            ctx.arc(this.x + calib.upgX, this.y + calib.upgY, 7, 0, Math.PI * 2);
            ctx.fillStyle = '#8e44ad'; ctx.fill();
            ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5; ctx.stroke();
            ctx.closePath();
        }

        // 8. Draw Potion Bar
        if (this.type === 'lab' && this.activePotion) {
            const barWidth = this.radius * 1.5;
            const barX = this.x - barWidth / 2;
            const barY = this.y + this.radius + 8;
            ctx.fillStyle = "rgba(0, 0, 0, 0.5)"; ctx.fillRect(barX, barY, barWidth, 6);
            ctx.fillStyle = this.activePotion.ready ? '#2ecc71' : '#f39c12';
            ctx.fillRect(barX, barY, barWidth * this.potionRatio, 6);
            ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1; ctx.strokeRect(barX, barY, barWidth, 6);
            ctx.font = '10px Arial'; ctx.fillText(`[${this.activePotion.type}]`, this.x, barY + 14);
        }

        ctx.restore();
    }

}

// ==========================================
// 5. MOUSE CONTROLS & UI CALCULATIONS
// ==========================================// --- NEW: True SVG Pixel-Perfect Hit Detection ---
function isMouseInUnit(b, mouseX, mouseY, ctx) {
    const bulgeBonus = Math.min(0.10, b.jellyCount / 10000); 
    const r = b.radius * (1 + bulgeBonus); 
    const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
    const path = SVG_PATHS[pathKey] || SVG_PATHS['basic'];
    const calib = UNIT_CALIBRATION[pathKey] || { s: 2.4, unitX: 0, unitY: 0 };
    
    const SVG_DRAWN_SIZE = 2800; 
    const CENTER_X = 1490; const CENTER_Y = 1450;
    
    ctx.save();
    ctx.translate(b.x + calib.unitX, b.y + calib.unitY);
    const scale = (r * calib.s) / SVG_DRAWN_SIZE; 
    ctx.scale(scale, scale);
    ctx.translate(-CENTER_X, -CENTER_Y);
    
    // Checks if the mouse is EXACTLY inside the SVG path!
    const isHit = ctx.isPointInPath(path, mouseX, mouseY);
    ctx.restore();
    
    return isHit;
}

// 1. Strictly checks if the mouse is directly over a button
function getHoveredButton(x, y) {
    for (let btn of upgradeButtons) {
        const dx = x - btn.x;
        const dy = y - btn.y;
        if ((dx * dx + dy * dy) <= (btn.r * btn.r)) return btn; 
    }
    return null;
}

// 2. Strictly checks if the mouse is directly inside the actual SVG shape
function getBuildingStrict(x, y) {
    for (let b of Object.values(clientBuildings)) {
        if (isMouseInUnit(b, x, y, ctx)) return b;
    }
    return null;
}

// 3. Determines hover state and extends a safe "bridge" to the menu buttons
function determineHoveredBuilding(mouseX, mouseY) {
    let buildingsArray = typeof clientBuildings !== 'undefined' ? Object.values(clientBuildings) : [];
    
    // 1. If we are ALREADY hovering a building, give it priority and extend its hover area!
    if (hoveredBuilding) {
        const b = hoveredBuilding;
        const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
        const calib = UNIT_CALIBRATION[pathKey] || { menuX: 0, menuY: 0 };
        
        const menuCenterX = b.x + calib.menuX;
        const menuCenterY = b.y + calib.menuY;

        // Is the mouse on the exact SVG unit OR in the extended menu bubble? (80px radius covers the buttons)
        let onUnit = isMouseInUnit(b, mouseX, mouseY, ctx);
        let onMenuArea = Math.hypot(mouseX - menuCenterX, mouseY - menuCenterY) <= 80;

        if (onUnit || onMenuArea) return b;
    }

    // 2. If not in the extended area, check all units using their true SVG shape
    for (let b of buildingsArray) {
        if (isMouseInUnit(b, mouseX, mouseY, ctx)) {
            return b;
        }
    }
    return null;
}

function updateUpgradeOptions() {
    upgradeButtons = [];
    if (!hoveredBuilding || hoveredBuilding.ownerId !== myPlayerId) return;

    const b = hoveredBuilding;
    const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
    const calib = UNIT_CALIBRATION[pathKey] || { menuX: 0, menuY: -50 };
    
    const btnRadius = 20; 
    const spacing = 10;

    const masterBtnX = b.x + calib.menuX; 
    const masterBtnY = b.y + calib.menuY; 

    if (b.type === 'basic') {
        const totalWidth = (3 * (btnRadius * 2)) + (2 * spacing);
        let startX = masterBtnX - (totalWidth / 2) + btnRadius; 
        
        UPGRADE_DATA.basic.forEach((opt, index) => {
            upgradeButtons.push({
                x: startX + (index * (btnRadius * 2 + spacing)), y: masterBtnY, r: btnRadius,
                icon: opt.icon, cost: opt.cost, enabled: b.jellyCount >= opt.cost,
                action: () => socket.emit('playerAction', { action: 'UPGRADE', buildingId: b.id, targetType: opt.type })
            });
        });
    } else if (b.type === 'lab') {
        const labButtons = [];
        if (b.level === 1) {
            labButtons.push({ icon: '❄️', cost: 25, type: 'potion', target: 'freeze' });
            labButtons.push({ icon: '⬆️', cost: 15, type: 'upgrade' });
        } else if (b.level === 2) {
            labButtons.push({ icon: '❄️', cost: 25, type: 'potion', target: 'freeze' });
            labButtons.push({ icon: '⬆️', cost: 20, type: 'upgrade' });
            labButtons.push({ icon: '☣️', cost: 30, type: 'potion', target: 'virus' });
        } else if (b.level === 3) {
            labButtons.push({ icon: '❄️', cost: 25, type: 'potion', target: 'freeze' });
            labButtons.push({ icon: '🩸', cost: 40, type: 'potion', target: 'red' });
            labButtons.push({ icon: '☣️', cost: 30, type: 'potion', target: 'virus' });
        }
        
        const totalWidth = (labButtons.length * (btnRadius * 2)) + ((labButtons.length - 1) * spacing);
        let startX = masterBtnX - (totalWidth / 2) + btnRadius; 
        
        labButtons.forEach((btn, index) => {
            let isEnabled = (btn.type === 'upgrade' || (btn.type === 'potion' && !b.activePotion)) ? b.jellyCount >= btn.cost : false;
            let isCancelBtn = (b.activePotion && b.activePotion.type === btn.target);
            if (isCancelBtn) isEnabled = true;

            let actionFunc = () => socket.emit('playerAction', { 
                action: btn.type === 'upgrade' ? 'UPGRADE' : (isCancelBtn ? 'CANCEL_POTION' : 'PREPARE_POTION'), 
                buildingId: b.id, potionType: btn.target 
            });
            
            upgradeButtons.push({
                x: startX + (index * (btnRadius * 2 + spacing)), y: masterBtnY, r: btnRadius,
                icon: btn.icon, cost: btn.cost, enabled: isEnabled, isCancel: isCancelBtn, action: actionFunc
            });
        });
        
    } else {
        const nextCost = UPGRADE_DATA[b.type][b.level];
        if (nextCost !== null) {
            upgradeButtons.push({
                x: masterBtnX, y: masterBtnY, r: btnRadius, icon: '⬆️', cost: nextCost,
                enabled: b.jellyCount >= nextCost,
                action: () => socket.emit('playerAction', { action: 'UPGRADE', buildingId: b.id })
            });
        }
    }
}

// --- GAME INPUTS ---
window.addEventListener('keydown', (e) => {
    // --- RADIAL MENU TEXT INPUT & HOTKEYS (EDITOR) ---
    if (typeof isEditMode !== 'undefined' && isEditMode) {
        
// 1. Gérer Ctrl+Z, Ctrl+Y, Ctrl+C, Ctrl+V (Compatible AZERTY/QWERTY)
        if (e.ctrlKey || e.metaKey) {
            const key = e.key.toLowerCase();
            
            // UNDO / REDO
            if (key === 'z') {
                e.preventDefault();
                if (e.shiftKey) redoEditor(); else undoEditor();            
                return;
            }
            if (key === 'y') {
                e.preventDefault(); redoEditor(); return;
            }
            
            // COPIER (Ctrl+C)
            if (key === 'c') {
                e.preventDefault();
                if (editorSelectedBuildings.length > 0) {
                    let centerX = editorSelectedBuildings.reduce((sum, b) => sum + b.x, 0) / editorSelectedBuildings.length;
                    let centerY = editorSelectedBuildings.reduce((sum, b) => sum + b.y, 0) / editorSelectedBuildings.length;
                    copiedGroup = editorSelectedBuildings.map(b => ({
                        offsetX: b.x - centerX, offsetY: b.y - centerY, 
                        radius: b.radius, ownerId: b.ownerId, jellyCount: b.jellyCount, type: b.type, level: b.level
                    }));
                }
                return;
            }
            
            // COLLER (Ctrl+V)
            if (key === 'v') {
                e.preventDefault();
                if (copiedGroup.length > 0) {
                    let newlyPasted = [];
                    copiedGroup.forEach(c => {
                        let newB = new Building({
                            // On utilise mousePos pour coller exactement sous la souris !
                            id: nextEditorId++, x: mousePos.x + c.offsetX, y: mousePos.y + c.offsetY,
                            radius: c.radius, ownerId: c.ownerId, jellyCount: c.jellyCount, type: c.type, level: c.level, status: 'normal'
                        });
                        editorBuildings.push(newB);
                        newlyPasted.push(newB);
                    });
                    editorSelectedBuildings = newlyPasted; // Sélection automatique !
                    saveEditorState();
                }
                return;
            }
        }

        // 2. Gérer la saisie des Jellies quand le menu radial est ouvert
        if (radialMenu.active && radialMenu.step === 'jellies') {
            if (e.key >= '0' && e.key <= '9') {
                if (radialMenu.data.jellies === "0") radialMenu.data.jellies = e.key;
                else radialMenu.data.jellies += e.key;
                if (parseInt(radialMenu.data.jellies) > 9999) radialMenu.data.jellies = "9999";
            } else if (e.key === 'Backspace') {
                radialMenu.data.jellies = radialMenu.data.jellies.slice(0, -1);
                if (radialMenu.data.jellies === "") radialMenu.data.jellies = "0";
            } else if (e.key === 'Enter') {
                if (radialMenu.targetUnit) {
                    radialMenu.targetUnit.jellyCount = parseInt(radialMenu.data.jellies);
                } else {
                    editorBuildings.push(new Building({
                        id: nextEditorId++, x: radialMenu.x, y: radialMenu.y, radius: 35,
                        ownerId: radialMenu.data.ownerId, jellyCount: parseInt(radialMenu.data.jellies),
                        type: radialMenu.data.type, level: radialMenu.data.level, status: 'normal'
                    }));
                }
                radialMenu.active = false;
                saveEditorState();
            }
            return; // Bloquer ici pendant la frappe
        }
    }

    // --- GAME HOTKEYS ---
    if (!isGameRunning) return; 
    
    // Space: Select ONLY 'basic' and 'building' (Factories)
    if (e.code === 'Space') {
        e.preventDefault();
        selectedBuildings = Object.values(clientBuildings).filter(b => 
            b.ownerId === myPlayerId && 
            (b.type === 'basic' || b.type === 'building')
        );
    }

    // Ctrl + A: Select ALL units - Compatible AZERTY/QWERTY
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'a') {
        e.preventDefault();
        selectedBuildings = Object.values(clientBuildings).filter(b => 
            b.ownerId === myPlayerId && 
            !(b.type === 'lab' && b.activePotion)
        );
    }
});

canvas.addEventListener('mousedown', (e) => {
    if (!isGameRunning || e.button !== 0) return;
    if (isEditMode) return;


    const clickedButton = getHoveredButton(mousePos.x, mousePos.y);

    if (clickedButton) {
        if (clickedButton.enabled) clickedButton.action();
        return; // Stop right here, don't select anything
    }

    const b = getBuildingStrict(mousePos.x, mousePos.y); // <-- Updated

    if (!b) {
        selectionBox.active = true;
        selectionBox.startX = mousePos.x;
        selectionBox.startY = mousePos.y;
        selectionBox.endX = mousePos.x;
        selectionBox.endY = mousePos.y;
        
        if (!e.shiftKey) {
            selectedBuildings = [];
            preDragSelection = [];
        } else {
            preDragSelection = [...selectedBuildings];
        }
    }
});

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    
    // ALWAYS update mousePos first so Radial Menu hovers work correctly
    if (typeof mousePos !== 'undefined') {
        mousePos.x = e.clientX - rect.left;
        mousePos.y = e.clientY - rect.top;
    }

// --- EDIT MODE DRAG LOGIC ---
    if (typeof isEditMode !== 'undefined' && isEditMode) {
        
        // BOX SELECT
        if (editorSelectionBox.active) {
            editorSelectionBox.endX = mousePos.x;
            editorSelectionBox.endY = mousePos.y;
            const minX = Math.min(editorSelectionBox.startX, editorSelectionBox.endX);
            const maxX = Math.max(editorSelectionBox.startX, editorSelectionBox.endX);
            const minY = Math.min(editorSelectionBox.startY, editorSelectionBox.endY);
            const maxY = Math.max(editorSelectionBox.startY, editorSelectionBox.endY);

            editorSelectedBuildings = [...editorPreDragSelection];
            editorBuildings.forEach(b => {
                const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
                const calib = UNIT_CALIBRATION[pathKey] || { unitX: 0, unitY: 0 };
                const visualX = b.x + calib.unitX;
                const visualY = b.y + calib.unitY;
                const closestX = Math.max(minX, Math.min(visualX, maxX));
                const closestY = Math.max(minY, Math.min(visualY, maxY));
                if ((visualX - closestX) ** 2 + (visualY - closestY) ** 2 <= b.radius ** 2) {
                    if (!editorSelectedBuildings.includes(b)) editorSelectedBuildings.push(b);
                }
            });
            return;
        }

        // DRAG & GROUPE
        if (draggedUnit) {
            let targetX = unitStartX + (mousePos.x - dragStartX);
            let targetY = unitStartY + (mousePos.y - dragStartY);
            if (e.shiftKey) {
                if (Math.abs(mousePos.x - dragStartX) > Math.abs(mousePos.y - dragStartY)) targetY = unitStartY;
                else targetX = unitStartX;
            }
            alignmentLines = [];
            if (e.ctrlKey) {
                targetX = Math.round(targetX / 50) * 50; targetY = Math.round(targetY / 50) * 50; alignmentPoints = []; 
            } else {
                // CORRECTION: Only snap to units that are NOT currently selected/moving
                let fixedBuildings = editorBuildings.filter(b => !editorSelectedBuildings.includes(b));
                let snap = calculateSmartSnap(targetX, targetY, draggedUnit, fixedBuildings);
                
                targetX = snap.x; targetY = snap.y; alignmentLines = snap.lines; alignmentPoints = snap.points; 
            }
            // Appliquer au groupe entier !
            if (editorSelectedBuildings.includes(draggedUnit)) {
                let dx = targetX - unitStartX;
                let dy = targetY - unitStartY;
                editorSelectedBuildings.forEach(b => {
                    let orig = groupOriginalPositions.get(b.id);
                    if (orig) { b.x = orig.x + dx; b.y = orig.y + dy; }
                });
            } else {
                draggedUnit.x = targetX; draggedUnit.y = targetY;
            }
        }
        return; 
    }

    // --- GAME MODE HOVER LOGIC ---
    if (!isGameRunning) return;

    const prevHover = hoveredBuilding;
    hoveredBuilding = determineHoveredBuilding(mousePos.x, mousePos.y);

    if (prevHover !== hoveredBuilding) {
        updateUpgradeOptions();
    }

    if (typeof selectionBox !== 'undefined' && selectionBox.active) {
        selectionBox.endX = mousePos.x;
        selectionBox.endY = mousePos.y;

        const minX = Math.min(selectionBox.startX, selectionBox.endX);
        const maxX = Math.max(selectionBox.startX, selectionBox.endX);
        const minY = Math.min(selectionBox.startY, selectionBox.endY);
        const maxY = Math.max(selectionBox.startY, selectionBox.endY);

        selectedBuildings = [...preDragSelection];

        Object.values(clientBuildings).forEach(b => {
            if (b.ownerId === myPlayerId && !(b.type === 'lab' && b.activePotion)) {
                const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
                const calib = UNIT_CALIBRATION[pathKey] || { unitX: 0, unitY: 0 };
                const visualX = b.x + calib.unitX;
                const visualY = b.y + calib.unitY;

                const closestX = Math.max(minX, Math.min(visualX, maxX));
                const closestY = Math.max(minY, Math.min(visualY, maxY));
                const distanceX = visualX - closestX;
                const distanceY = visualY - closestY;
                
                if ((distanceX * distanceX + distanceY * distanceY) <= (b.radius * b.radius)) {
                    if (!selectedBuildings.some(s => s.id === b.id)) selectedBuildings.push(b);
                }
            }
        });
    }
});

canvas.addEventListener('mouseup', () => {
    // 1. Arrêter l'incrémentation rapide des Jellies (+ / -)
    if (typeof jellyHoldTimer !== 'undefined' && jellyHoldTimer !== null) {
        clearTimeout(jellyHoldTimer);
        jellyHoldTimer = null;
    }

    // 2. Relâcher le glisser-déposer dans l'éditeur
    if (typeof isEditMode !== 'undefined' && isEditMode && draggedUnit) {
        draggedUnit = null;
        groupDragAnchor = null;
        alignmentLines = []; 
        alignmentPoints = []; // Effacer les lignes de Snapping
        saveEditorState();
    }
    
    // 3. ARRÊTER la boîte de sélection de l'éditeur (La solution à ton bug !)
    if (typeof editorSelectionBox !== 'undefined') {
        editorSelectionBox.active = false;
    }

    // 4. Arrêter la boîte de sélection du mode jeu classique
    if (typeof selectionBox !== 'undefined') {
        selectionBox.active = false;
    }
});

canvas.addEventListener('click', (e) => {
    // --- EDIT MODE DELETION ---
    if (typeof isEditMode !== 'undefined' && isEditMode) {
        
        // THE FIX: If we just interacted with the radial menu, ignore this click!
        if (ignoreNextClick) {
            ignoreNextClick = false;
            return;
        }

        const rect = canvas.getBoundingClientRect();
        const clickX = e.clientX - rect.left;
        const clickY = e.clientY - rect.top;

        for (let i = 0; i < editorBuildings.length; i++) {
            let b = editorBuildings[i];
            const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
            const calib = UNIT_CALIBRATION[pathKey] || { upgX: 25, upgY: 25 };
            
            // Check if clicking exact upgrade button coordinates
            if (Math.hypot(clickX - (b.x + calib.upgX), clickY - (b.y + calib.upgY)) <= 12) {
                editorBuildings.splice(i, 1);
                editorSelectedBuildings = []; // <-- THE FIX: Clear selection!
                saveEditorState();
                return;
            }
        }
        return; // Important: Stop here so game click logic doesn't fire
    }
    if (!isGameRunning) return;

    // Ignore click event if we were just clicking a UI button
    if (getHoveredButton(mousePos.x, mousePos.y)) return;

    const target = getBuildingStrict(mousePos.x, mousePos.y); // <-- Updated
    if (target) {
        if (selectedBuildings.length > 0) {
            if (clickTimer === null) {
                clickTimer = setTimeout(() => {
                    executeSend(target, 0.5);
                    clickTimer = null;
                }, 250);
            }
        } else if (target.ownerId === myPlayerId) {
            if (e.shiftKey) {
                const idx = selectedBuildings.findIndex(b => b.id === target.id);
                if (idx === -1) selectedBuildings.push(target);
                else selectedBuildings.splice(idx, 1);
            } else {
                selectedBuildings = [target];
            }
        }
    }
});

canvas.addEventListener('dblclick', () => {
    if (!isGameRunning) return;
    
    // Ignore click event if we were just clicking a UI button
    if (getHoveredButton(mousePos.x, mousePos.y)) return;

    const target = getBuildingStrict(mousePos.x, mousePos.y); // <-- Updated

    if (target && selectedBuildings.length > 0) {
        if (clickTimer !== null) { clearTimeout(clickTimer); clickTimer = null; }
        executeSend(target, 1.0);
    }
});

function executeSend(target, percentage) {
    // 1. Check if any selected building is a Lab with a completed potion
    const readyLab = selectedBuildings.find(b => b.type === 'lab' && b.activePotion && b.activePotion.ready);

    if (readyLab) {
        // Fire the potion instantly!
        socket.emit('playerAction', { 
            action: 'USE_POTION', 
            labId: readyLab.id, 
            targetId: target.id 
        });
        selectedBuildings = []; // Clear selection after firing
        return; // Stop here so it doesn't send troops
    }

    // 2. Normal troop sending logic (ignores labs that are currently brewing)
    const validSources = selectedBuildings.filter(b => !(b.type === 'lab' && b.activePotion));
    if (validSources.length === 0) return;

    socket.emit('playerAction', { 
        action: 'SEND_TROOPS', 
        sourceIds: validSources.map(b => b.id), 
        targetId: target.id, 
        percentage: percentage 
    });

    selectedBuildings = []; // Clear selection after attacking
}

// ==========================================
// 6. MAP EDITOR & SERIALIZATION
// ==========================================
let isEditMode = false;
let ignoreNextClick = false;
let editorBuildings = []; 
let nextEditorId = 1;

// --- ÉTAT DE LA SÉLECTION DE GROUPE ---
let editorSelectedBuildings = [];
let editorSelectionBox = { active: false, startX: 0, startY: 0, endX: 0, endY: 0 };
let editorPreDragSelection = [];
let groupDragAnchor = null; 
let groupOriginalPositions = new Map(); // Pour garder les distances relatives pendant le drag
let copiedGroup = []; // Le presse-papiers pour Copier/Coller

let draggedUnit = null;
let dragStartX = 0;
let dragStartY = 0;
let unitStartX = 0;
let unitStartY = 0;

let editorHistory = [];
let editorHistoryIndex = -1; // Suit où on se trouve dans l'historique
const editorUI = document.getElementById('editor-ui');

// --- RADIAL MENU STATE ---
let radialMenu = {
    active: false,
    x: 0, y: 0,
    step: 'player', // Steps: 'player' -> 'type' -> 'level' -> 'jellies' (or 'edit' for existing)
    targetUnit: null, 
    data: { ownerId: 0, type: 'basic', level: 1, jellies: "10" }
};

// Prevent the default browser right-click menu in Edit Mode
window.addEventListener('contextmenu', (e) => {
    if (typeof isEditMode !== 'undefined' && isEditMode) {
        e.preventDefault();
    }
});

let jellyHoldTimer = null;

// Fonction pour incrémenter/décrémenter rapidement en restant appuyé
function startJellyHold(dir) {
    let speed = 1;
    let val = parseInt(radialMenu.data.jellies) + dir;
    if(val >= 0 && val <= 9999) radialMenu.data.jellies = val.toString();
    
    jellyHoldTimer = setTimeout(function tick() {
        speed += 0.5; // Accélération dynamique
        let v = parseInt(radialMenu.data.jellies) + dir * Math.floor(speed);
        if (v < 0) v = 0; 
        if (v > 9999) v = 9999;
        radialMenu.data.jellies = v.toString();
        jellyHoldTimer = setTimeout(tick, 50); // Répète toutes les 50ms
    }, 300); // Délai initial de 300ms avant que ça s'emballe
}

// --- ADVANCED SMART ALIGNMENT ENGINE ---
let alignmentLines = []; 
let alignmentPoints = []; // Tracks crosshairs for mirror snaps

function calculateSmartSnap(targetX, targetY, draggedObj, others) {
    const SNAP_TOLERANCE = 8;
    let result = { x: targetX, y: targetY, lines: [], points: [] };
    let r = draggedObj.radius;
    let cW = typeof canvas !== 'undefined' ? canvas.width : 800;
    let cH = typeof canvas !== 'undefined' ? canvas.height : 600;

    let snappedX = false;
    let snappedY = false;

    // 1. MAP CENTER AXES SNAPPING (Blue Lines)
    if (Math.abs(result.x - cW / 2) < SNAP_TOLERANCE) {
        result.x = cW / 2; snappedX = true;
        result.lines.push({ x1: result.x, y1: 0, x2: result.x, y2: cH, color: '#3498db' });
    }
    if (Math.abs(result.y - cH / 2) < SNAP_TOLERANCE) {
        result.y = cH / 2; snappedY = true;
        result.lines.push({ x1: 0, y1: result.y, x2: cW, y2: result.y, color: '#3498db' });
    }

    for (let other of others) {
        if (other.id === draggedObj.id) continue;
        let oR = other.radius;

        // 2. MIRRORED GHOST SNAPPING (Purple Lines - Symmetry)
        let mirrorX = cW - other.x;
        let mirrorY = cH - other.y;
        
        if (!snappedX && Math.abs(result.x - mirrorX) < SNAP_TOLERANCE) {
            result.x = mirrorX; snappedX = true;
            result.lines.push({ x1: result.x, y1: 0, x2: result.x, y2: cH, color: '#9b59b6' });
            result.points.push({ x: result.x, y: other.y });
        }
        if (!snappedY && Math.abs(result.y - mirrorY) < SNAP_TOLERANCE) {
            result.y = mirrorY; snappedY = true;
            result.lines.push({ x1: 0, y1: result.y, x2: cW, y2: result.y, color: '#9b59b6' });
            result.points.push({ x: other.x, y: result.y });
        }

        // 3. STANDARD ALIGNMENT (Red Lines - Edges and Centers)
        // X-Axis
        if (!snappedX) {
            if (Math.abs(result.x - other.x) < SNAP_TOLERANCE) {
                result.x = other.x; snappedX = true;
                result.lines.push({ x1: result.x, y1: 0, x2: result.x, y2: cH, color: '#e74c3c' });
            } else if (Math.abs((result.x - r) - (other.x + oR)) < SNAP_TOLERANCE) {
                result.x = other.x + oR + r; snappedX = true;
                result.lines.push({ x1: result.x - r, y1: 0, x2: result.x - r, y2: cH, color: '#e74c3c' });
            } else if (Math.abs((result.x + r) - (other.x - oR)) < SNAP_TOLERANCE) {
                result.x = other.x - oR - r; snappedX = true;
                result.lines.push({ x1: result.x + r, y1: 0, x2: result.x + r, y2: cH, color: '#e74c3c' });
            }
        }
        // Y-Axis
        if (!snappedY) {
            if (Math.abs(result.y - other.y) < SNAP_TOLERANCE) {
                result.y = other.y; snappedY = true;
                result.lines.push({ x1: 0, y1: result.y, x2: cW, y2: result.y, color: '#e74c3c' });
            } else if (Math.abs((result.y - r) - (other.y + oR)) < SNAP_TOLERANCE) {
                result.y = other.y + oR + r; snappedY = true;
                result.lines.push({ x1: 0, y1: result.y - r, x2: cW, y2: result.y - r, color: '#e74c3c' });
            } else if (Math.abs((result.y + r) - (other.y - oR)) < SNAP_TOLERANCE) {
                result.y = other.y - oR - r; snappedY = true;
                result.lines.push({ x1: 0, y1: result.y + r, x2: cW, y2: result.y + r, color: '#e74c3c' });
            }
        }
    }
    return result;
}


// --- DRAW RADIAL MENU ---
function drawRadialMenu(ctx) {
    if (!radialMenu.active) return;
    const { x, y, step, data } = radialMenu;
    
    ctx.save();
    
    // 1. Fond sombre
    ctx.beginPath(); ctx.arc(x, y, 110, 0, Math.PI*2);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fill();

// 2. Dessin des parts de tarte (Sauf Jellies)
    if (step !== 'jellies') {
        let options = [];
        if (step === 'player') {
            options = [
                { val: 0, color: '#bdc3c7', text: 'Neutral' },
                { val: 1, color: '#3498db', text: 'P1' },
                { val: 2, color: '#e74c3c', text: 'P2' },
                { val: 3, color: '#f1c40f', text: 'P3' },
                { val: 4, color: '#9b59b6', text: 'P4' }
            ];
            // On cache Paste si on est en train de modifier une unité !
            if (copiedGroup.length > 0 && !radialMenu.targetUnit && !radialMenu.isModifying) {
                options.push({ val: 'paste', color: '#2ecc71', text: 'Paste' });
            }
        } else if (step === 'type') {
            // ... (GARDE LE RESTE DU CODE TYPE ET LEVEL IDENTIQUE ICI) ...
            options = [
                { val: 'basic', text: 'Basic' },
                { val: 'building', text: 'Building' },
                { val: 'fort', text: 'Fort' },
                { val: 'lab', text: 'Lab' }
            ];
        } else if (step === 'level') {
            const maxLvl = data.type === 'building' ? 5 : (data.type === 'basic' ? 1 : 3);
            for(let i=1; i<=maxLvl; i++) options.push({ val: i, text: 'Lvl ' + i });
        } else if (step === 'edit') {
            // NOW 5 OPTIONS
            options = [
                { val: 'delete', color: '#e74c3c', text: 'Delete' },
                { val: 'modify', color: '#2ecc71', text: 'Modify' }, 
                { val: 'to_top', color: '#9b59b6', text: 'To Top' }, // <-- NEW
                { val: 'copy', color: '#3498db', text: 'Copy' },
                { val: 'edit_jellies', color: '#f1c40f', text: 'Set Jellies' }
            ];
        } else if (step === 'edit_group') {
            // NOW 6 OPTIONS
            options = [
                { val: 'delete', color: '#e74c3c', text: 'Delete' },
                { val: 'copy', color: '#3498db', text: 'Copy' },
                { val: 'flip_h', color: '#e67e22', text: 'Flip H' },
                { val: 'flip_v', color: '#e67e22', text: 'Flip V' },
                { val: 'to_top', color: '#9b59b6', text: 'To Top' }, // <-- NEW
                { val: 'edit_jellies', color: '#f1c40f', text: 'Set Jellies' }
            ];
        }
        const sliceAngle = (Math.PI * 2) / options.length;
        let mouseAngle = null;
        if (typeof mousePos !== 'undefined') {
            let dx = mousePos.x - x;
            let dy = mousePos.y - y;
            if (Math.hypot(dx, dy) > 20 && Math.hypot(dx, dy) < 110) {
                mouseAngle = Math.atan2(dy, dx);
                if (mouseAngle < 0) mouseAngle += Math.PI * 2;
            }
        }

for (let i = 0; i < options.length; i++) {
            let startAngle = i * sliceAngle - (Math.PI / 2) - (sliceAngle / 2);
            let endAngle = startAngle + sliceAngle;
            let isHovered = false;

            if (mouseAngle !== null) {
                let normMouse = mouseAngle + (Math.PI / 2) + (sliceAngle / 2);
                if (normMouse > Math.PI * 2) normMouse -= Math.PI * 2;
                if (Math.floor(normMouse / sliceAngle) === i) isHovered = true;
            }

            // Draw Wedge Background & Borders
            ctx.beginPath(); ctx.moveTo(x, y); ctx.arc(x, y, 105, startAngle, endAngle); ctx.closePath();
            ctx.fillStyle = isHovered ? 'rgba(255,255,255,0.25)' : 'rgba(255,255,255,0.0)'; ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.3)'; ctx.lineWidth = 1; ctx.stroke();

            let midAngle = startAngle + (sliceAngle / 2);
            ctx.textAlign = 'center'; ctx.textBaseline = 'middle';

            // --- NEW: RADIAL POSITIONING FOR SVGS & TEXT ---
// --- COMPACT & CENTERED LAYOUT FOR SVGS & TEXT ---
            if (step === 'type' || step === 'level') {
                let pColor = players[data.ownerId] ? players[data.ownerId].color : '#bdc3c7';
                let bType = step === 'type' ? options[i].val : data.type;
                let bLevel = step === 'level' ? options[i].val : 1;

                let centerR = 66; // Standard distance from center
                let svgRadius = 15; // Standard size
                let extraY = 0; // Custom vertical nudge
                
                // THE FIX: Target Building Lvl 3 & 4 and nudge them down!
                if (bType === 'building' && (bLevel === 3 || bLevel === 4)) {
                    svgRadius = 13; // Shrink slightly so tentacles don't touch the lines
                    extraY = 6;     // Push them straight down by 6 pixels
                }

                let contentX = x + Math.cos(midAngle) * centerR;
                let contentY = y + Math.sin(midAngle) * centerR + extraY;

                let svgX = contentX;
                let svgY = contentY - 8; // SVG slightly above text
                let textX = contentX;
                let textY = contentY + 16; // Text strictly below SVG
                
                let fakeB = { x: svgX, y: svgY, radius: svgRadius, jellyCount: 0, type: bType, level: bLevel, status: 'normal' };
                
                // Scale the calibration offsets so they don't fly away
                const baseCalib = UNIT_CALIBRATION[fakeB.type === 'basic' ? 'basic' : `${fakeB.type}_${fakeB.level}`] || { s: 2.4, unitX: 0, unitY: 0 };
                let baseSize = (bType === 'basic') ? 35 : 50;
                let ratio = svgRadius / baseSize; 
                
                const menuCalib = { 
                    s: baseCalib.s, 
                    unitX: baseCalib.unitX * ratio, 
                    unitY: baseCalib.unitY * ratio 
                };
                
                drawCustomUnit(ctx, fakeB, pColor, 10, isHovered, menuCalib);

                // Draw the Text Label
                ctx.fillStyle = 'white'; 
                ctx.font = isHovered ? 'bold 12px Arial' : '11px Arial';
                ctx.fillText(options[i].text, textX, textY);

            } else {
                // Standard Text Positioning for other menus
                let contentX = x + Math.cos(midAngle) * 65;
                let contentY = y + Math.sin(midAngle) * 65;
                
                ctx.fillStyle = options[i].color || 'white';
                ctx.font = isHovered ? 'bold 15px Arial' : 'bold 13px Arial';
                ctx.fillText(options[i].text, contentX, contentY);
            }
        }
    } else {
        // 3. Interface Jellies (Dégagée vers le bas)
        ctx.fillStyle = 'white'; ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText('Set Jellies', x, y - 65);
        
        ctx.fillStyle = '#f1c40f'; ctx.font = 'bold 26px Arial';
        ctx.fillText(data.jellies, x, y + 45); // Plus de '_' !

        // Bouton (-)
        ctx.beginPath(); ctx.arc(x - 50, y + 45, 15, 0, Math.PI*2);
        ctx.fillStyle = '#e74c3c'; ctx.fill();
        ctx.fillStyle = 'white'; ctx.font = 'bold 18px Arial'; ctx.fillText('-', x - 50, y + 47);

        // Bouton (+)
        ctx.beginPath(); ctx.arc(x + 50, y + 45, 15, 0, Math.PI*2);
        ctx.fillStyle = '#2ecc71'; ctx.fill();
        ctx.fillStyle = 'white'; ctx.font = 'bold 18px Arial'; ctx.fillText('+', x + 50, y + 47);

        // Bouton Done
        ctx.beginPath(); ctx.roundRect(x - 30, y + 75, 60, 25, 5);
        ctx.fillStyle = '#3498db'; ctx.fill();
        ctx.fillStyle = 'white'; ctx.font = 'bold 14px Arial'; ctx.fillText('Done', x, y + 87.5);
    }

// 4. Bouton Central (Back / Cancel) 
    // Si on est à la première étape de modification (Player), c'est une croix rouge !
    let isRootMenu = step === 'edit' || step === 'edit_group' || (step === 'player' && !radialMenu.targetUnit) || (step === 'player' && radialMenu.isModifying);
    let centerIcon = isRootMenu ? 'X' : '🔙';
    let centerColor = isRootMenu ? '#e74c3c' : '#34495e';

    ctx.beginPath(); ctx.arc(x, y, 20, 0, Math.PI*2);
    ctx.fillStyle = centerColor; ctx.fill();
    ctx.strokeStyle = '#2c3e50'; ctx.lineWidth = 2; ctx.stroke();
    ctx.fillStyle = 'white'; ctx.font = centerIcon === 'X' ? 'bold 16px Arial' : '18px Arial';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(centerIcon, x, y + (centerIcon === 'X' ? 0 : 2));

    ctx.restore();
}

function saveEditorState() {
    // Si on a fait "Undo" puis qu'on place un nouvel objet, on efface le futur alternatif
    if (editorHistoryIndex < editorHistory.length - 1) {
        editorHistory = editorHistory.slice(0, editorHistoryIndex + 1);
    }
    
    const snapshot = editorBuildings.map(b => new Building({
        id: b.id, x: b.x, y: b.y, radius: b.radius,
        ownerId: b.ownerId, jellyCount: b.jellyCount,
        type: b.type, level: b.level,
        status: 'normal', activePotion: null, potionProgress: 0, potionRatio: 0
    }));
    
    editorHistory.push(snapshot);
    editorHistoryIndex++;
}

function undoEditor() {
    if (editorHistoryIndex > 0) { 
        editorHistoryIndex--;
        const previousState = editorHistory[editorHistoryIndex];
        editorBuildings = previousState.map(b => new Building(b)); 
        editorSelectedBuildings = []; // Clear selection on Undo!
    }
}

function redoEditor() {
    if (editorHistoryIndex < editorHistory.length - 1) {
        editorHistoryIndex++;
        const nextState = editorHistory[editorHistoryIndex];
        editorBuildings = nextState.map(b => new Building(b));
        editorSelectedBuildings = []; // Clear selection on Redo!
    }
}

document.getElementById('btn-open-editor').addEventListener('click', () => {
    uiLayer.style.display = 'none';
    canvas.style.display = 'block';
    editorUI.style.display = 'block';
    
    isEditMode = true;
    editorBuildings = []; 
    editorHistory = []; 
    editorHistoryIndex = -1;
    nextEditorId = 1;
    
    saveEditorState(); 
    requestAnimationFrame(editorLoop); 
});

document.getElementById('btn-exit-editor').addEventListener('click', () => {
    isEditMode = false;
    editorUI.style.display = 'none';
    canvas.style.display = 'none';
    uiLayer.style.display = 'flex'; 
}); 
    
document.getElementById('btn-undo-editor').addEventListener('click', () => {
    undoEditor();
});

document.getElementById('btn-redo-editor').addEventListener('click', () => {
    redoEditor();
});

canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;

    // --- GAME UI CLICKS ---
    if (typeof isGameRunning !== 'undefined' && isGameRunning && hoveredBuilding && hoveredBuilding.ownerId === myPlayerId) {
        for (let btn of upgradeButtons) {
            if (Math.hypot(clickX - btn.x, clickY - btn.y) <= btn.r) {
                if (btn.enabled && btn.action) btn.action();
                return;
            }
        }
    }

// --- EDIT MODE LOGIC ---
    if (typeof isEditMode !== 'undefined' && isEditMode) {
        
        // 1. GESTION DU MENU RADIAL
        if (radialMenu.active && e.button === 0) {
            ignoreNextClick = true; // <-- THE FIX: Block the upcoming click event!
            
            let dx = clickX - radialMenu.x;
            let dy = clickY - radialMenu.y;
            let dist = Math.hypot(dx, dy);

            // Clic sur les boutons de l'étape Jellies
            if (radialMenu.step === 'jellies') {
                if (Math.hypot(clickX - (radialMenu.x - 50), clickY - (radialMenu.y + 45)) <= 15) { startJellyHold(-1); return; }
                if (Math.hypot(clickX - (radialMenu.x + 50), clickY - (radialMenu.y + 45)) <= 15) { startJellyHold(1); return; }
                
                // Bouton Done
                if (clickX >= radialMenu.x - 30 && clickX <= radialMenu.x + 30 && clickY >= radialMenu.y + 75 && clickY <= radialMenu.y + 100) {
                    let newJellies = parseInt(radialMenu.data.jellies);
                    if (radialMenu.targetUnit) {
                        if (radialMenu.isModifying) {
                            // On applique TOUT d'un coup à la fin de la modification !
                            radialMenu.targetUnit.ownerId = radialMenu.data.ownerId;
                            radialMenu.targetUnit.type = radialMenu.data.type;
                            radialMenu.targetUnit.level = radialMenu.data.level;
                            radialMenu.targetUnit.jellyCount = newJellies;
                        } else {
                            // On éditait juste les jellies
                            radialMenu.targetUnit.jellyCount = newJellies;
                            if (editorSelectedBuildings.includes(radialMenu.targetUnit)) editorSelectedBuildings.forEach(b => b.jellyCount = newJellies);
                        }
                    } else {
                        // Création d'une nouvelle unité
                        editorBuildings.push(new Building({
                            id: nextEditorId++, x: radialMenu.x, y: radialMenu.y, radius: 35,
                            ownerId: radialMenu.data.ownerId, jellyCount: newJellies, type: radialMenu.data.type, level: radialMenu.data.level, status: 'normal'
                        }));
                    }
                    radialMenu.active = false;
                    radialMenu.isModifying = false; 
                    saveEditorState();
                    return;
                }
            }

            // Bouton Central (Annuler/Retour)
            if (dist <= 20) {
                if (radialMenu.step === 'edit' || radialMenu.step === 'edit_group' || (radialMenu.step === 'player' && !radialMenu.isModifying)) {
                    radialMenu.active = false; // Fermer
                } else if (radialMenu.step === 'player' && radialMenu.isModifying) {
                    radialMenu.step = 'edit'; // Annuler la modification
                    radialMenu.isModifying = false;
                } else if (radialMenu.step === 'type') {
                    radialMenu.step = 'player';
                } else if (radialMenu.step === 'level') {
                    radialMenu.step = 'type';
                } else if (radialMenu.step === 'jellies') {
                    if (radialMenu.targetUnit && !radialMenu.isModifying) {
                        radialMenu.step = editorSelectedBuildings.includes(radialMenu.targetUnit) && editorSelectedBuildings.length > 1 ? 'edit_group' : 'edit';
                    } else if (radialMenu.data.type === 'basic') {
                        radialMenu.step = 'type';
                    } else {
                        radialMenu.step = 'level';
                    }
                }
                return;
            }
            if (dist > 110) { radialMenu.active = false; return; }

// Sélection des Parts de Tarte
            if (dist > 20 && dist <= 110) {
                let angle = Math.atan2(dy, dx); if (angle < 0) angle += Math.PI * 2;
                
// Update the option counts for the math!
                let optionsCount = 0;
                if (radialMenu.step === 'player') optionsCount = (copiedGroup.length > 0 && !radialMenu.isModifying && !radialMenu.targetUnit) ? 6 : 5;
                else if (radialMenu.step === 'type') optionsCount = 4;
                else if (radialMenu.step === 'level') optionsCount = radialMenu.data.type === 'building' ? 5 : (radialMenu.data.type === 'basic' ? 1 : 3);
                else if (radialMenu.step === 'edit') optionsCount = 5; // <-- WAS 4, NOW 5
                else if (radialMenu.step === 'edit_group') optionsCount = 6; // <-- WAS 5, NOW 6                
                let sliceAngle = (Math.PI * 2) / optionsCount;
                let normMouse = angle + (Math.PI/2) + (sliceAngle/2);
                if (normMouse > Math.PI*2) normMouse -= Math.PI*2;
                let selectedIndex = Math.floor(normMouse / sliceAngle);

                if (radialMenu.step === 'player') {
                    if (copiedGroup.length > 0 && !radialMenu.isModifying && !radialMenu.targetUnit && selectedIndex === 5) {
                        let newlyPasted = []; // On stocke les nouvelles unités créées
                        copiedGroup.forEach(c => {
                            let newB = new Building({
                                id: nextEditorId++, x: radialMenu.x + c.offsetX, y: radialMenu.y + c.offsetY,
                                radius: c.radius, ownerId: c.ownerId, jellyCount: c.jellyCount, type: c.type, level: c.level, status: 'normal'
                            });
                            editorBuildings.push(newB);
                            newlyPasted.push(newB);
                        });
                        editorSelectedBuildings = newlyPasted; // <-- THE FIX: Sélection automatique !
                        radialMenu.active = false; saveEditorState();
                    } else { radialMenu.data.ownerId = selectedIndex; radialMenu.step = 'type'; }
                } else if (radialMenu.step === 'type') {
                    const types = ['basic', 'building', 'fort', 'lab'];
                    radialMenu.data.type = types[selectedIndex];
                    radialMenu.step = radialMenu.data.type === 'basic' ? 'jellies' : 'level';
                } else if (radialMenu.step === 'level') {
                    radialMenu.data.level = selectedIndex + 1; radialMenu.step = 'jellies';
} else if (radialMenu.step === 'edit') {
                    if (selectedIndex === 0) { // DELETE
                        editorBuildings = editorBuildings.filter(b => b.id !== radialMenu.targetUnit.id);
                        editorSelectedBuildings = []; radialMenu.active = false; saveEditorState();
                    } else if (selectedIndex === 1) { // MODIFY
                        radialMenu.isModifying = true;
                        radialMenu.data = { ownerId: radialMenu.targetUnit.ownerId, type: radialMenu.targetUnit.type, level: radialMenu.targetUnit.level, jellies: radialMenu.targetUnit.jellyCount.toString() };
                        radialMenu.step = 'player'; 
                    } else if (selectedIndex === 2) { // TO TOP (NEW!)
                        // Remove it from current spot, push it to the very end of the array
                        editorBuildings = editorBuildings.filter(b => b.id !== radialMenu.targetUnit.id);
                        editorBuildings.push(radialMenu.targetUnit);
                        radialMenu.active = false; saveEditorState();
                    } else if (selectedIndex === 3) { // COPY
                        let b = radialMenu.targetUnit;
                        copiedGroup = [{ offsetX: 0, offsetY: 0, radius: b.radius, ownerId: b.ownerId, jellyCount: b.jellyCount, type: b.type, level: b.level }];
                        radialMenu.active = false;
                    } else if (selectedIndex === 4) { // JELLIES
                        radialMenu.isModifying = false;
                        radialMenu.step = 'jellies'; radialMenu.data.jellies = radialMenu.targetUnit.jellyCount.toString();
                    }
                } else if (radialMenu.step === 'edit_group') {
                    if (selectedIndex === 0) { // DELETE
                        editorBuildings = editorBuildings.filter(b => !editorSelectedBuildings.includes(b));
                        editorSelectedBuildings = []; radialMenu.active = false; saveEditorState();
                    } else if (selectedIndex === 1) { // COPY
                        let centerX = editorSelectedBuildings.reduce((sum, b) => sum + b.x, 0) / editorSelectedBuildings.length;
                        let centerY = editorSelectedBuildings.reduce((sum, b) => sum + b.y, 0) / editorSelectedBuildings.length;
                        copiedGroup = editorSelectedBuildings.map(b => ({
                            offsetX: b.x - centerX, offsetY: b.y - centerY, radius: b.radius, ownerId: b.ownerId, jellyCount: b.jellyCount, type: b.type, level: b.level
                        }));
                        radialMenu.active = false;
                    } else if (selectedIndex === 2 || selectedIndex === 3) { // FLIP
                        let minVal = Infinity, maxVal = -Infinity; let isH = selectedIndex === 2;
                        editorSelectedBuildings.forEach(b => { let val = isH ? b.x : b.y; if (val < minVal) minVal = val; if (val > maxVal) maxVal = val; });
                        let center = (minVal + maxVal) / 2;
                        editorSelectedBuildings.forEach(b => { if (isH) b.x = center - (b.x - center); else b.y = center - (b.y - center); });
                        radialMenu.active = false; saveEditorState();
                    } else if (selectedIndex === 4) { // TO TOP (NEW!)
                        // Remove all selected units from array, then push them all to the end
                        editorBuildings = editorBuildings.filter(b => !editorSelectedBuildings.includes(b));
                        editorBuildings.push(...editorSelectedBuildings);
                        radialMenu.active = false; saveEditorState();
                    } else if (selectedIndex === 5) { // JELLIES
                        radialMenu.step = 'jellies'; radialMenu.data.jellies = radialMenu.targetUnit.jellyCount.toString();
                    }
                }
            }
            return;
        }
// 2. CLIC DROIT POUR OUVRIR LE MENU
        if (e.button === 2) {
            let clickedExisting = null;
            for (let i = editorBuildings.length - 1; i >= 0; i--) {
                if (isMouseInUnit(editorBuildings[i], clickX, clickY, ctx)) { clickedExisting = editorBuildings[i]; break; }
            }
            radialMenu.active = true; radialMenu.x = clickX; radialMenu.y = clickY;
            
            if (clickedExisting) {
                radialMenu.targetUnit = clickedExisting;
                // Si on clique sur une unité qui fait partie d'une sélection multiple
                if (editorSelectedBuildings.includes(clickedExisting) && editorSelectedBuildings.length > 1) {
                    radialMenu.step = 'edit_group';
                } else {
                    radialMenu.step = 'edit';
                }
            } else {
                // ---> THE FIX: Clic dans le vide = on désélectionne tout ! <---
                editorSelectedBuildings = []; 
                
                radialMenu.targetUnit = null; 
                radialMenu.step = 'player';
                radialMenu.data = { ownerId: 0, type: 'basic', level: 1, jellies: "10" };
            }
            return;
        }

        // 3. CLIC GAUCHE : SÉLECTION ET DRAG DE GROUPE
        if (e.button === 0) {
            // Empecher le drag sur le bouton rouge 'X'
            for (let i = 0; i < editorBuildings.length; i++) {
                let b = editorBuildings[i];
                const calib = UNIT_CALIBRATION[b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`] || { upgX: 25, upgY: 25 };
                if (Math.hypot(clickX - (b.x + calib.upgX), clickY - (b.y + calib.upgY)) <= 12) return;
            }

            let clickedExisting = null;
            for (let i = editorBuildings.length - 1; i >= 0; i--) {
                if (isMouseInUnit(editorBuildings[i], clickX, clickY, ctx)) { clickedExisting = editorBuildings[i]; break; }
            }

            if (clickedExisting) {
                // Gestion de la touche Ctrl (Sélection multiple)
                if (e.ctrlKey || e.metaKey) {
                    let idx = editorSelectedBuildings.findIndex(b => b.id === clickedExisting.id);
                    if (idx === -1) editorSelectedBuildings.push(clickedExisting);
                    else editorSelectedBuildings.splice(idx, 1);
                } else {
                    // Si on clique sur une unité non sélectionnée sans Ctrl, elle devient la seule sélection
                    if (!editorSelectedBuildings.includes(clickedExisting)) {
                        editorSelectedBuildings = [clickedExisting];
                    }
                }
                
// On commence le Drag de Groupe ! L'unité cliquée est l'ancre.
                draggedUnit = clickedExisting; 
                groupDragAnchor = clickedExisting;
                dragStartX = clickX; 
                dragStartY = clickY;
                unitStartX = clickedExisting.x; // <-- CORRECTION: Reset X anchor
                unitStartY = clickedExisting.y; // <-- CORRECTION: Reset Y anchor
                groupOriginalPositions.clear();
                editorSelectedBuildings.forEach(b => {
                    groupOriginalPositions.set(b.id, { x: b.x, y: b.y });
                });
            } else {
                // On a cliqué dans le vide : Box Select !
                if (!e.ctrlKey) editorSelectedBuildings = [];
                editorSelectionBox.active = true;
                editorSelectionBox.startX = clickX; editorSelectionBox.startY = clickY;
                editorSelectionBox.endX = clickX; editorSelectionBox.endY = clickY;
                editorPreDragSelection = [...editorSelectedBuildings];
            }
            return;
        }
        return; 
    }
});



canvas.addEventListener('mouseup', () => {
    if (isEditMode && draggedUnit) {
        draggedUnit = null;
        saveEditorState(); 
    }
});

document.getElementById('btn-export-map').addEventListener('click', () => {
    const rawData = editorBuildings.map(b => ({
        id: b.id, x: b.x, y: b.y, radius: b.radius,
        ownerId: b.ownerId, jellyCount: b.jellyCount,
        type: b.type, level: b.level,
        status: b.status, maxJelliesOverride: b.maxJelliesOverride || null,
        activePotion: null, potionProgress: 0, potionRatio: 0
    }));

    const jsonString = JSON.stringify(rawData);
    const base64Code = btoa(jsonString);
    
    navigator.clipboard.writeText(base64Code).then(() => {
        alert("Map Code copied to clipboard!\nPaste it in the Main Menu to play!");
    });
});

function editorLoop() {
    if (!isEditMode) return;
    
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines
    ctx.strokeStyle = "rgba(255, 255, 255, 0.1)";
    ctx.lineWidth = 1;
    for(let i = 0; i < canvas.width; i += 50) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke(); }
    for(let i = 0; i < canvas.height; i += 50) { ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke(); }


editorBuildings.forEach(b => {
        b.draw(ctx);
        
        // ONLY draw the red 'X' if the radial menu is closed
        if (!radialMenu.active) {
            const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
            const calib = UNIT_CALIBRATION[pathKey] || { upgX: 25, upgY: 25 };
            const delX = b.x + calib.upgX;
            const delY = b.y + calib.upgY;

            ctx.beginPath(); ctx.arc(delX, delY, 12, 0, Math.PI*2);
            ctx.fillStyle = '#e74c3c'; ctx.fill();
            ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5; ctx.stroke();
            ctx.fillStyle = 'white'; ctx.font = 'bold 12px Arial';
            ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText('X', delX, delY);
        }
    });

// Dessiner un anneau autour des unités sélectionnées (Ajusté à la position visuelle !)
    editorSelectedBuildings.forEach(b => {
        const pathKey = b.type === 'basic' ? 'basic' : `${b.type}_${b.level || 1}`;
        const calib = UNIT_CALIBRATION[pathKey] || { unitX: 0, unitY: 0 };
        const visualX = b.x + calib.unitX;
        const visualY = b.y + calib.unitY;

        ctx.beginPath(); 
        ctx.arc(visualX, visualY, b.radius + 6, 0, Math.PI*2);
        ctx.strokeStyle = '#3498db'; 
        ctx.lineWidth = 3; 
        ctx.setLineDash([5,5]); 
        ctx.stroke(); 
        ctx.setLineDash([]);
    });

    // Dessiner la boîte de Box Select
    if (editorSelectionBox.active) {
        const w = mousePos.x - editorSelectionBox.startX;
        const h = mousePos.y - editorSelectionBox.startY;
        ctx.fillStyle = "rgba(52, 152, 219, 0.25)"; ctx.fillRect(editorSelectionBox.startX, editorSelectionBox.startY, w, h);
        ctx.strokeStyle = "rgba(52, 152, 219, 0.8)"; ctx.strokeRect(editorSelectionBox.startX, editorSelectionBox.startY, w, h);
    }

// --- DRAW SMART SNAPPING LINES & GHOST POINTS ---
    if (alignmentLines.length > 0) {
        ctx.save();
        ctx.lineWidth = 1.5;
        ctx.setLineDash([5, 5]); 
        
        alignmentLines.forEach(line => {
            ctx.beginPath();
            ctx.strokeStyle = line.color || '#e74c3c';
            ctx.moveTo(line.x1, line.y1);
            ctx.lineTo(line.x2, line.y2);
            ctx.stroke();
        });

        // Draw Ghost Point Crosshairs for Symmetry
        if (typeof alignmentPoints !== 'undefined') {
            ctx.setLineDash([]);
            ctx.strokeStyle = '#9b59b6'; // Purple for mirror points
            alignmentPoints.forEach(pt => {
                ctx.beginPath();
                ctx.moveTo(pt.x - 10, pt.y); ctx.lineTo(pt.x + 10, pt.y);
                ctx.moveTo(pt.x, pt.y - 10); ctx.lineTo(pt.x, pt.y + 10);
                ctx.stroke();
            });
        }
        ctx.restore();
    }

    drawRadialMenu(ctx); // Render the new menu on top!

    requestAnimationFrame(editorLoop);
}







// ==========================================
// 7. RENDER LOOP
// ==========================================
function gameLoop() {
    if (!isGameRunning) return; // Completely stops rendering if in lobby

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (selectedBuildings.length > 0) {
        ctx.strokeStyle = "rgba(255, 255, 255, 0.9)";
        ctx.lineWidth = 3;
        ctx.setLineDash([]); 

        const endX = hoveredBuilding ? hoveredBuilding.x : mousePos.x;
        const endY = hoveredBuilding ? hoveredBuilding.y : mousePos.y;

        selectedBuildings.forEach(b => {
            ctx.beginPath();
            ctx.moveTo(b.x, b.y);
            ctx.lineTo(endX, endY);
            ctx.stroke();
        });
    }

    Object.values(clientBuildings).forEach(b => b.draw(ctx));

// --- DRAW HOMING PROJECTILES ---
    clientProjectiles.forEach(proj => {
        ctx.beginPath();
        ctx.arc(proj.x, proj.y, 6, 0, Math.PI * 2); // Smaller radius (6) than packages
        ctx.fillStyle = players[proj.ownerId] ? players[proj.ownerId].color : '#bdc3c7';
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.closePath();
    });

    // Draw Packages
    clientPackages.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 14, 0, Math.PI * 2);
        ctx.fillStyle = players[p.ownerId] ? players[p.ownerId].color : '#ff0000';
        ctx.fill();
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.closePath();

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(Math.floor(p.jellyCount), p.x, p.y + 1);
    });

upgradeButtons.forEach(btn => {
        ctx.beginPath();
        ctx.arc(btn.x, btn.y, btn.r, 0, Math.PI * 2);
        ctx.fillStyle = btn.enabled ? (btn.isCancel ? '#e74c3c' : '#27ae60') : '#7f8c8d'; 
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.closePath();
        
        ctx.fillStyle = '#ffffff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        
        ctx.font = '14px Arial';
        ctx.fillText(btn.icon, btn.x, btn.y - 5);
        
        ctx.font = 'bold 11px Arial';
        ctx.fillText(btn.cost, btn.x, btn.y + 9);
    });

    if (selectionBox.active) {
        const w = selectionBox.endX - selectionBox.startX;
        const h = selectionBox.endY - selectionBox.startY;
        ctx.fillStyle = "rgba(52, 152, 219, 0.25)";
        ctx.fillRect(selectionBox.startX, selectionBox.startY, w, h);
        ctx.strokeStyle = "rgba(52, 152, 219, 0.8)";
        ctx.strokeRect(selectionBox.startX, selectionBox.startY, w, h);
    }

    requestAnimationFrame(gameLoop);
}
